mapper.select:
select o.*, u.name as userName, exists(select 1 from review r where r.order_id = o.id) as has_review from explore_order o left join user u on o.user_id = u.id
and ( o.order_no like concat('%',#{keyword},'%') or o.item_name like concat('%',#{keyword},'%') or u.name like concat('%',#{keyword},'%') or o.contact_name like concat('%',#{keyword},'%') or o.contact_phone like concat('%',#{keyword},'%') )
and o.order_no like concat('%',#{orderNo},'%')
and o.contact_name like concat('%',#{contactName},'%')
and o.status = #{status}
and o.order_type = #{orderType}
and o.user_id = #{userId}
order by o.create_time desc

mapper.update:
update explore_order
remark = #{remark}, contact_name = #{contactName}, contact_phone = #{contactPhone}, reserve_time = #{reserveTime}, request_id = #{requestId}, people_count = #{peopleCount}, expire_at = #{expireAt}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select o.id, o.order_no, o.order_type, o.item_name, o.amount, o.people_count,
       o.contact_name, o.contact_phone, o.reserve_time, o.status, o.create_time, u.name as user_name
from explore_order o left join user u on o.user_id = u.id

    o.id > #{lastId} and o.id <= #{snapshot.maxId}

        and (o.order_no like concat('%',#{snapshot.keyword},'%') or o.item_name like concat('%',#{snapshot.keyword},'%')
            or u.name like concat('%',#{snapshot.keyword},'%') or o.contact_name like concat('%',#{snapshot.keyword},'%')
            or o.contact_phone like concat('%',#{snapshot.keyword},'%'))

    and o.order_no like concat('%',#{snapshot.orderNo},'%')
    and o.contact_name like concat('%',#{snapshot.contactName},'%')
    and o.status = #{snapshot.dataStatus}
    and o.order_type = #{snapshot.orderType}
    and o.user_id = #{snapshot.userId}
    and o.create_time >= #{snapshot.startTime}
    and o.create_time <= #{snapshot.endTime}

order by o.id
limit #{limit}
